// Parity with the Go implementation.
//
// The vector file is generated by Go from its own code:
//
//   go test ./internal/scan/schema -run Vectors -update
//
// This test reads that file and asserts the JavaScript agrees. A failure here
// means the two implementations have drifted, which would corrupt any baseline
// written by one path and read by the other.

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

import {
  fingerprint,
  fingerprintLoose,
  normaliseSelector,
  normaliseText,
  truncateBytes,
} from '../src/fingerprint.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const vectorPath = path.resolve(here, '../../../internal/scan/schema/testdata/fingerprints.json');

let vectors;
try {
  vectors = JSON.parse(readFileSync(vectorPath, 'utf8'));
} catch (err) {
  throw new Error(
    `Cannot read ${vectorPath}. Generate it with:\n` +
      '  go test ./internal/scan/schema -run Vectors -update\n' +
      `(${err.message})`,
  );
}

test('the vector file has content', () => {
  assert.ok(Array.isArray(vectors) && vectors.length > 5, 'expected a list of vectors');
});

for (const [i, v] of vectors.entries()) {
  test(`vector ${i}: ${v.note}`, () => {
    // The intermediate values are compared too, so a failure names the
    // normaliser that drifted instead of only showing two different hashes.
    assert.equal(
      normaliseSelector(v.selector),
      v.normalised_selector,
      `normaliseSelector disagrees with Go for ${JSON.stringify(v.selector)}`,
    );
    assert.equal(
      normaliseText(v.html),
      v.normalised_text,
      `normaliseText disagrees with Go for ${JSON.stringify(v.html)}`,
    );
    assert.equal(fingerprint(v.rule, v.selector), v.fingerprint, 'exact fingerprint');
    assert.equal(fingerprintLoose(v.rule, v.html), v.fingerprint_loose, 'loose fingerprint');
  });
}

// The properties the vectors protect, asserted directly so a parity failure can
// be diagnosed without decoding hashes.

test('BEM element names do not collapse into one another', () => {
  // This was a real bug: a build-hash heuristic stripped `_subtitle` and
  // `_title` alike, so both selectors shared a fingerprint and a baseline entry
  // for one silently absorbed a new violation on the other.
  const a = fingerprint('color-contrast', '.hero__title');
  const b = fingerprint('color-contrast', '.hero__subtitle');
  assert.notEqual(a, b, '.hero__title and .hero__subtitle must not share a fingerprint');
});

test('truncation counts bytes, not UTF-16 units, and never splits a character', () => {
  const cyrillic = 'ы'.repeat(200); // two bytes each
  const cut = truncateBytes(cyrillic);
  assert.ok(new TextEncoder().encode(cut).length <= 120, 'over the byte limit');
  assert.equal(cut.length, 60, 'expected 60 two-byte characters to fit in 120 bytes');
  assert.ok(!cut.includes('�'), 'truncation produced a replacement character');

  // An emoji is four bytes and two UTF-16 units; it must be kept or dropped
  // whole.
  const emoji = 'a'.repeat(118) + '🎉tail';
  const cutEmoji = truncateBytes(emoji);
  assert.ok(!cutEmoji.includes('�'), 'split a surrogate pair');
  assert.equal(cutEmoji, 'a'.repeat(118), 'the emoji did not fit and should have been dropped');
});

test("Go's whitespace class, not JavaScript's", () => {
  // U+00A0 is whitespace to JavaScript's \s and not to Go's. Collapsing it here
  // would silently disagree with the server on any page using non-breaking
  // spaces, which is most pages with prices or names in them.
  const withNbsp = normaliseText('<p>29 per month</p>');
  assert.ok(withNbsp.includes(' '), 'a non-breaking space must survive normalisation');
});

test('the iframe separator normalises the same however it is spaced', () => {
  assert.equal(normaliseSelector('#f >>> img'), normaliseSelector('#f>>>img'));
});
